list_tax_custom_profiles.code:
import {taxCustomProfiles} from 'webcommander-sdk';

const response = await taxCustomProfiles.listTaxCustomProfiles(client, {limit: 20});
for (const customProfile of response.map.custom_profiles) {
    console.log(customProfile.id, customProfile.name, customProfile.rate_rules_count);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_tax_custom_profile.code:
import {taxCustomProfiles} from 'webcommander-sdk';

const response = await taxCustomProfiles.createTaxCustomProfile(client, {
    custom_profile: {name: 'Wholesale customers', description: 'Rates for wholesale accounts'},
});
console.log(response.map.custom_profile.id);

get_tax_custom_profile.code:
import {taxCustomProfiles} from 'webcommander-sdk';

const response = await taxCustomProfiles.getTaxCustomProfile(client, 1);
const customProfile = response.map.custom_profile;
console.log(customProfile.name, customProfile.description, customProfile.rate_rules_count);
for (const rateRule of customProfile.rate_rules) {
    console.log(rateRule.id, rateRule.name, rateRule.zones_count);
}

